{"command": "echo "=== Landing page content ===" && curl -s "https://ivxholding.com" 2>&1 | python3 -c "
import sys
html = sys.stdin.read()
print(f'Page size: {len(html)} bytes')
# Extract title
import re
title = re.search(r'<title[^>]*>(.*?)</title>', html, re.IGNORECASE | re.DOTALL)
if title: print(f'Title: {title.group(1).strip()[:100]}')
# Extract meta description
desc = re.search(r'<meta[^>]*name=[\"\\']description[\"\\'][^>]*content=[\"\\'](.*?)[\"\\']', html, re.IGNORECASE)
if desc: print(f'Description: {desc.group(1).strip()[:150]}')
# Extract h1
h1 = re.search(r'<h1[^>]*>(.*?)</h1>', html, re.IGNORECASE | re.DOTALL)
if h1: print(f'H1: {h1.group(1).strip()[:100]}')
# Check for IVX branding
if 'ivx' in html.lower(): print('IVX branding: FOUND')
if 'holdings' in html.lower(): print('Holdings branding: FOUND')
" 2>&1"}

