{"command": "# Get all 112 agents grouped by division
curl -s "https://api.ivxholding.com/api/ivx/agents" 2>&1 | python3 -c "
import sys,json
d=json.loads(sys.stdin.read())
agents = d.get('agents',[])
divisions = {}
for a in agents:
    div = a.get('division','?')
    if div not in divisions:
        divisions[div] = []
    divisions[div].append(a)

print(f'Total agents: {len(agents)}')
print(f'Divisions: {len(divisions)}')
print()
for div in sorted(divisions.keys()):
    print(f'=== Division {div} ({len(divisions[div])} agents) ===')
    for a in divisions[div]:
        print(f'  #{a[\"agentNumber\"]:>3} | {a[\"agentId\"]} | {a[\"name\"]} | {a[\"role\"]}')
    print()
" 2>&1"}
